package au.monster.tracker;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.provider.MediaStore;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import android.graphics.drawable.GradientDrawable;
import java.io.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Native receipt review, manual purchases, explicit goods receipt and operating expenses. */
public final class BusinessActivity extends Activity {
    private Store store;private BusinessStore business;private LinearLayout root,body;private TextView status,receiptLabel;private boolean busy,dead;
    private final ExecutorService io=Executors.newSingleThreadExecutor();private final List<View> controls=new ArrayList<>();
    private Purchases.Receipt attachment;private Uri cameraUri;private final List<Purchases.Line> draftLines=new ArrayList<>();private LinearLayout lineList;
    private EditText supplier,reference,note,expenseAmount,expenseGst,category;private Button receiptDateButton;private String formKind,draftDocumentId;private CatalogStore.View flavours;private long draftRecordedAt;private Long date=System.currentTimeMillis();
    @Override public void onCreate(Bundle state){super.onCreate(state);store=new Store(this);business=new BusinessStore(store);if(state!=null&&state.getString("cameraUri")!=null)cameraUri=Uri.parse(state.getString("cameraUri"));if(state!=null&&state.getString("formKind")!=null){form(state.getString("formKind"));restoreDraft(state);}else showList();}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(cameraUri!=null)b.putString("cameraUri",cameraUri.toString());if(formKind!=null){b.putString("formKind",formKind);b.putString("draftDocumentId",draftDocumentId);b.putLong("draftRecordedAt",draftRecordedAt);Map<String,Object> draft=new LinkedHashMap<>();draft.put("supplier",supplier.getText().toString());draft.put("reference",reference.getText().toString());draft.put("note",note.getText().toString());draft.put("date",date);List<Object> lines=new ArrayList<>();for(var l:draftLines)lines.add(Purchases.lineMap(l));draft.put("lines",lines);if(formKind.equals("expense")){draft.put("amount",expenseAmount.getText().toString());draft.put("gst",expenseGst.getText().toString());draft.put("category",category.getText().toString());}b.putString("draft",Json.write(draft));if(attachment!=null)b.putString("attachment",attachment.hash());}}
    private void restoreDraft(Bundle saved){try{draftDocumentId=saved.getString("draftDocumentId",draftDocumentId);draftRecordedAt=saved.getLong("draftRecordedAt",draftRecordedAt);String json=saved.getString("draft");if(json!=null){var draft=Purchases.map(Json.parse(json));supplier.setText(Purchases.str(draft,"supplier"));reference.setText(Purchases.str(draft,"reference"));note.setText(Purchases.str(draft,"note"));date=draft.get("date")==null?null:Purchases.num(draft,"date");receiptDateButton.setText(Ledger.displayTime(date));for(Object l:Purchases.list(draft.get("lines")))draftLines.add(Purchases.line(l));if(formKind.equals("purchase"))drawLines();else {expenseAmount.setText(Purchases.str(draft,"amount"));expenseGst.setText(Purchases.str(draft,"gst"));category.setText(Purchases.str(draft,"category"));}}String hash=saved.getString("attachment");if(hash!=null&&hash.matches("[a-f0-9]{64}")){job(()->{File file=new File(getCacheDir(),"receipt-review/"+hash);try(InputStream in=new FileInputStream(file)){return Purchases.receipt(readBytes(in));}},r->{attachment=r;receiptLabel.setText("Original receipt retained after reopening: "+r.hash().substring(0,12));});}}catch(Exception e){error(new IllegalStateException("Unsaved review could not be recovered. Saved records remain unchanged."));}}
    @Override public void onBackPressed(){if(formKind!=null){new AlertDialog.Builder(this).setTitle("Leave unsaved review?").setMessage("Only confirmed saves become documents. Discard this unfinished review?").setNegativeButton("Keep editing",null).setPositiveButton("Leave",(d,w)->showList()).show();}else super.onBackPressed();}
    @Override protected void onDestroy(){dead=true;io.execute(store::close);io.shutdown();super.onDestroy();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private void shell(String title){controls.clear();root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(16),dp(16),dp(16));root.setBackgroundColor(0xff101410);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(16),insets.getSystemWindowInsetTop()+dp(8),dp(16),insets.getSystemWindowInsetBottom()+dp(8));return insets;});setContentView(root);root.requestApplyInsets();root.addView(text(title,24));status=text("Offline · all changes are saved only after confirmation",14);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(0xfff0f5eb);t.setTextSize(size);t.setPadding(0,dp(8),0,dp(8));return t;}
    private Button button(String value,Runnable run){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextColor(0xff101410);b.setMinHeight(dp(56));GradientDrawable shape=new GradientDrawable();shape.setColor(0xffb6f552);shape.setCornerRadius(dp(12));b.setBackground(shape);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));b.setLayoutParams(p);b.setOnClickListener(v->{if(!busy)run.run();});controls.add(b);return b;}
    private EditText field(LinearLayout box,String label,String value,int type){box.addView(text(label,15));EditText e=new EditText(this);e.setInputType(type);e.setText(value);e.setTextColor(0xfff0f5eb);e.setMinHeight(dp(52));e.setSingleLine(type!=InputType.TYPE_CLASS_TEXT);box.addView(e);controls.add(e);return e;}
    private EditText money(LinearLayout box,String label){return field(box,label,"0.00",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);}
    private void error(Throwable e){String message=e.getMessage()==null?"Nothing was saved. Check the information and try again.":e.getMessage();if(!dead)new AlertDialog.Builder(this).setTitle("Could not complete").setMessage(message).setPositiveButton("OK",null).show();}
    private <T> void job(Callable<T> task,java.util.function.Consumer<T> done){if(busy)return;busy=true;for(View v:controls)v.setEnabled(false);status.setText("Working locally…");io.execute(()->{try{T result=task.call();runOnUiThread(()->{if(dead)return;busy=false;for(View v:controls)v.setEnabled(true);done.accept(result);});}catch(Throwable e){runOnUiThread(()->{if(dead)return;busy=false;for(View v:controls)v.setEnabled(true);status.setText("No changes saved.");error(e);});}});}
    private void showList(){formKind=null;attachment=null;draftLines.clear();shell("Purchases & expenses");body.addView(button("New supplier purchase",()->form("purchase")));body.addView(button("Record operating expense",()->form("expense")));body.addView(button("View append-only audit",this::showAudit));body.addView(button("Back to tracker",this::finish));job(business::view,state->{body.addView(text("Operating expenses: "+Ledger.money(state.expenses()),19));for(int i=state.documents().size()-1;i>=0;i--){var d=state.documents().get(i);body.addView(button(d.supplier()+" · "+Ledger.money(d.amount())+"\n"+d.kind()+" · "+Ledger.displayTime(d.date())+(state.cancelled().contains(d.id())?" · cancelled":""),()->details(d)));}status.setText("Invoice recording does not add stock. Confirm actual deliveries separately.");});}
    private void form(String kind){flavours=new CatalogStore(store).view();formKind=kind;draftDocumentId=Ledger.id();draftRecordedAt=System.currentTimeMillis();attachment=null;draftLines.clear();date=System.currentTimeMillis();shell(kind.equals("purchase")?"Review supplier purchase":"Record expense");supplier=field(body,"Supplier / payee","",InputType.TYPE_CLASS_TEXT);reference=field(body,"Invoice / receipt reference (optional)","",InputType.TYPE_CLASS_TEXT);long[] time={date};Button dateButton=button(Ledger.displayTime(date),()->{});receiptDateButton=dateButton;dateButton.setOnClickListener(v->{if(busy)return;ZonedDateTime z=Instant.ofEpochMilli(time[0]).atZone(Ledger.PERTH);new DatePickerDialog(this,(picker,y,m,d)->{date=LocalDate.of(y,m+1,d).atStartOfDay(Ledger.PERTH).toInstant().toEpochMilli();time[0]=date;dateButton.setText(Ledger.displayTime(date));},z.getYear(),z.getMonthValue()-1,z.getDayOfMonth()).show();});body.addView(dateButton);CheckBox unknown=new CheckBox(this);unknown.setText("Historical receipt date is unknown");unknown.setTextColor(0xfff0f5eb);unknown.setMinHeight(dp(48));unknown.setOnCheckedChangeListener((b,checked)->{date=checked?null:time[0];dateButton.setEnabled(!checked);});body.addView(unknown);controls.add(unknown);
        receiptLabel=text("No receipt attached. Manual entry is available offline.",14);body.addView(receiptLabel);body.addView(button("Import original JPG / PNG / PDF",this::importReceipt));body.addView(button("Take live receipt photo",this::photograph));body.addView(button("Read attached receipt with offline OCR",this::ocr));
        if(kind.equals("purchase")){lineList=new LinearLayout(this);lineList.setOrientation(1);body.addView(lineList);body.addView(button("Add product / multipack / expense line",this::addLine));body.addView(button("Scan saved product barcode",()->startActivityForResult(new Intent(this,CameraActivity.class).putExtra("mode","barcode"),54)));body.addView(text("Enter gross costs and actual GST shown on the invoice. No GST registration is assumed. Goods remain unreceived until a separate confirmation.",14));}
        else {category=field(body,"Expense category","Operating expense",InputType.TYPE_CLASS_TEXT);expenseAmount=money(body,"Gross expense (AUD)");expenseGst=money(body,"GST shown on receipt (AUD; zero if none)");}
        note=field(body,"Optional note","",InputType.TYPE_CLASS_TEXT);body.addView(button("Confirm document — do not add stock",()->{try{long amount=0,gst=0;if(kind.equals("purchase"))for(var l:draftLines){amount+=l.cost();gst+=l.gst();}else {amount=Ledger.cents(expenseAmount.getText().toString());gst=Ledger.cents(expenseGst.getText().toString());}var doc=new Purchases.Document(draftDocumentId,kind,supplier.getText().toString(),reference.getText().toString(),date,draftRecordedAt,amount,gst,kind.equals("expense")?category.getText().toString():"",note.getText().toString(),attachment==null?null:attachment.hash(),draftLines);Purchases.Receipt original=attachment;new AlertDialog.Builder(this).setTitle("Save reviewed document?").setMessage(doc.supplier()+" · "+Ledger.money(doc.amount())+"\nNo stock will be added. All original information remains in history.").setNegativeButton("Keep reviewing",null).setPositiveButton("Save document",(d,w)->job(()->{business.add(doc,original);return true;},ok->showList())).show();}catch(Exception e){error(e);}}));body.addView(button("Cancel review",this::onBackPressed));}
    private void addLine(){addLine(null);} private void addLine(String scannedProduct){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);fields.setPadding(dp(16),0,dp(16),0);EditText product=field(fields,"Product / flavour","Monster",InputType.TYPE_CLASS_TEXT),packs=field(fields,"Number of packs","1",InputType.TYPE_CLASS_NUMBER),size=field(fields,"Cans per pack","24",InputType.TYPE_CLASS_NUMBER),cost=money(fields,"Gross line total (AUD)"),gst=money(fields,"Line GST shown (AUD)");CheckBox stock=new CheckBox(this);stock.setText("Inventory item (untick for expense)");stock.setChecked(true);fields.addView(stock);fields.addView(text("Received flavour (legacy remains unassigned)",15));Spinner flavour=new Spinner(this);flavour.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,flavours.products().stream().map(Catalog.Product::name).toArray(String[]::new)));if(scannedProduct!=null)for(int i=0;i<flavours.products().size();i++)if(flavours.products().get(i).id().equals(scannedProduct)){flavour.setSelection(i);product.setText(flavours.products().get(i).name());}fields.addView(flavour);ScrollView scroll=new ScrollView(this);scroll.addView(fields);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Purchase line").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Add line",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{var line=new Purchases.Line(Ledger.id(),product.getText().toString(),Long.parseLong(packs.getText().toString()),Long.parseLong(size.getText().toString()),Ledger.cents(cost.getText().toString()),Ledger.cents(gst.getText().toString()),stock.isChecked(),stock.isChecked()?flavours.products().get(flavour.getSelectedItemPosition()).id():null);draftLines.add(line);drawLines();dialog.dismiss();}catch(Exception e){error(e);}}));dialog.show();}
    private void drawLines(){lineList.removeAllViews();long sum=0;for(var l:new ArrayList<>(draftLines)){sum+=l.cost();Button b=button(l.product()+" · "+l.packs()+" × "+l.packSize()+" · "+Ledger.money(l.cost())+(l.stock()?" stock":" expense")+"\nTap to remove this unsaved line",()->{draftLines.remove(l);drawLines();});lineList.addView(b);}lineList.addView(text("Invoice total: "+Ledger.money(sum),20));}
    private void details(Purchases.Document doc){shell(doc.supplier()+" · "+doc.kind());formKind=null;body.addView(text("ID: "+doc.id()+"\nReference: "+doc.reference()+"\nDate: "+Ledger.displayTime(doc.date())+"\nGross total: "+Ledger.money(doc.amount())+"\nGST shown: "+Ledger.money(doc.gst())+"\n"+doc.note(),16));if(doc.receiptHash()!=null)body.addView(button("Open original receipt",()->{Uri uri=Uri.parse("content://"+getPackageName()+".receipts/original/"+doc.receiptHash());try{Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,business.receiptMime(doc.receiptHash())).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(intent);}catch(Exception e){error(new IllegalStateException("Install an offline viewer for this receipt type, or export a full backup to retain its original bytes."));}}));job(business::view,state->{boolean cancelled=state.cancelled().contains(doc.id());for(var l:doc.lines()){long received=state.received().getOrDefault(l.id(),0L);body.addView(text(l.product()+" · ordered "+l.cans()+" cans · received "+received+"\nCost: "+Ledger.money(l.cost())+" · GST: "+Ledger.money(l.gst())+(l.stock()?"":" · operating expense"),16));if(l.stock()&&!cancelled&&received<l.cans())body.addView(button("Confirm received goods: "+l.product(),()->receive(l,l.cans()-received)));}if(!cancelled)body.addView(button(doc.kind().equals("expense")?"Undo expense (keep original)":"Cancel outstanding purchase (keep history)",()->cancel(doc)));else body.addView(text("Cancelled; original history retained. Previously received stock remains until an explicit stock undo.",15));body.addView(button("All purchases / expenses",this::showList));status.setText("Only confirmed deliveries create inventory restocks. Use History to undo a mistaken delivery.");});}
    private void receive(Purchases.Line line,long remaining){CatalogStore.View available=new CatalogStore(store).view();LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);Spinner flavour=new Spinner(this);flavour.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,available.products().stream().map(Catalog.Product::name).toArray(String[]::new)));for(int i=0;i<available.products().size();i++)if(available.products().get(i).id().equals(line.productId()))flavour.setSelection(i);fields.addView(flavour);EditText q=new EditText(this);fields.addView(q);q.setInputType(InputType.TYPE_CLASS_NUMBER);q.setText(String.valueOf(remaining));String id=Ledger.id();long now=System.currentTimeMillis();AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Have these goods arrived?").setMessage("Available to receive: "+remaining+" cans. Confirm only cans physically received; partial deliveries are supported.").setView(fields).setNegativeButton("Not received / cancel",null).setPositiveButton("Confirm received",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{long quantity=Long.parseLong(q.getText().toString());Purchases.allocatedCost(line,line.cans()-remaining,quantity);dialog.dismiss();job(()->{business.receive(id,line.id(),quantity,now,"",available.products().get(flavour.getSelectedItemPosition()).id());return true;},ok->showList());}catch(Exception e){error(e);}}));dialog.show();}
    private void cancel(Purchases.Document doc){EditText why=new EditText(this);why.setHint("Reason (required)");String id=Ledger.id();new AlertDialog.Builder(this).setTitle(doc.kind().equals("expense")?"Undo expense?":"Cancel unreceived remainder?").setMessage("The original stays in the audit. Existing deliveries are not silently removed; undo any incorrect restock in History first.").setView(why).setNegativeButton("Keep",null).setPositiveButton("Confirm correction",(d,w)->job(()->{business.cancel(id,doc.id(),why.getText().toString());return true;},ok->showList())).show();}
    private void showAudit(){formKind=null;shell("Append-only audit");body.addView(button("Back to purchases",this::showList));job(business::audit,rows->{for(int i=rows.size()-1;i>=Math.max(0,rows.size()-200);i--){var m=rows.get(i);body.addView(text(Purchases.str(m,"action")+"\n"+Purchases.str(m,"entityId")+"\n"+Ledger.displayTime(m.get("date")==null?null:Purchases.num(m,"date"))+"\nRecorded: "+Ledger.displayTime(Purchases.num(m,"recordedAt")),14));}status.setText("Latest 200 audit records. Full history and attachments are included in JSON backups.");});}
    private byte[] readBytes(InputStream in)throws IOException{try(ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>Purchases.MAX_RECEIPT)throw new IOException("Receipt exceeds 16 MB.");out.write(buffer,0,n);}return out.toByteArray();}}
    private void importReceipt(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","application/pdf"});try{startActivityForResult(i,51);}catch(ActivityNotFoundException e){error(e);}}
    private void photograph(){try{startActivityForResult(new Intent(this,CameraActivity.class).putExtra("mode","receipt"),53);}catch(ActivityNotFoundException e){error(e);}}
    private void ocr(){if(attachment==null){error(new IllegalArgumentException("Photograph or attach a receipt first."));return;}Purchases.Receipt original=attachment;job(()->ReceiptParser.parse(ReceiptOcr.scan(this,original)),suggestions->{TextView raw=text("OCR suggestions can be wrong. Review all fields and product lines. No stock is added.\n\nSupplier: "+suggestions.supplier()+"\nDate: "+Ledger.displayTime(suggestions.date())+"\nTotal: "+(suggestions.total()==null?"not detected":Ledger.money(suggestions.total()))+"\nGST shown: "+(suggestions.gst()==null?"not detected":Ledger.money(suggestions.gst()))+"\n\n"+suggestions.raw(),15);ScrollView scroll=new ScrollView(this);scroll.addView(raw);new AlertDialog.Builder(this).setTitle("Review on-device OCR").setView(scroll).setNegativeButton("Keep manual values",null).setPositiveButton("Apply draft suggestions",(d,w)->{supplier.setText(suggestions.supplier());reference.setText(suggestions.reference());date=suggestions.date();receiptDateButton.setText(Ledger.displayTime(date));if(formKind.equals("expense")){if(suggestions.total()!=null)expenseAmount.setText(Ledger.inputMoney(suggestions.total()));if(suggestions.gst()!=null)expenseGst.setText(Ledger.inputMoney(suggestions.gst()));}else {draftLines.clear();long gross=0;for(var item:suggestions.items())gross+=item.total();long tax=suggestions.gst()==null?0:suggestions.gst();if(tax>gross)tax=0;long cumulative=0,allocated=0;for(var item:suggestions.items()){cumulative+=item.total();long next=gross==0?0:tax*cumulative/gross;boolean stock=item.description().toLowerCase(Locale.ROOT).contains("monster");draftLines.add(new Purchases.Line(Ledger.id(),item.description(),item.packs(),item.packSize(),item.total(),next-allocated,stock,stock?Catalog.LEGACY:null));allocated=next;}drawLines();}status.setText("Draft updated only. Tap a line to remove it and add corrected details before confirming.");}).show();});}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK)return;if(request==54&&data!=null){String code=data.getStringExtra("barcode");try{Catalog.Product p=new CatalogStore(store).lookup(code);if(p==null){new AlertDialog.Builder(this).setTitle("Barcode not assigned").setMessage("Assign this barcode to a saved flavour first. No stock was changed.").setNegativeButton("Later",null).setPositiveButton("Assign flavour",(d,w)->startActivity(new Intent(this,CatalogActivity.class).putExtra("barcode",code))).show();}else {status.setText("Saved barcode: "+p.name()+". Add/review the purchase line and select this flavour before confirming.");addLine(p.id());}}catch(Exception e){error(e);}return;}Uri uri=request==52?cameraUri:(data==null?null:data.getData());if(uri==null||formKind==null)return;job(()->{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Receipt unavailable");byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>Purchases.MAX_RECEIPT)throw new IOException("Receipt exceeds 16 MB.");out.write(buffer,0,n);}var r=Purchases.receipt(out.toByteArray());File dir=new File(getCacheDir(),"receipt-review");dir.mkdirs();try(FileOutputStream staged=new FileOutputStream(new File(dir,r.hash()))){staged.write(r.content());}return r;}},r->{attachment=r;receiptLabel.setText("Original attached: "+r.mime()+" · "+r.content().length+" bytes\nDuplicate fingerprint: "+r.hash().substring(0,12));status.setText("Review supplier, date, quantities, gross prices and GST before confirming.");if((request==52||request==53)&&uri!=null){if(cameraUri!=null)revokeUriPermission(cameraUri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);new File(getCacheDir(),"receipt-camera/"+uri.getLastPathSegment()).delete();cameraUri=null;}});}
}
